// Idempotent: once report_ready it returns the stored report without re-scanning.
import { NextRequest, NextResponse } from "next/server";
import { fulfil, readSession } from "@/lib/fulfil";
import { dbConfigured } from "@/lib/db";

export const runtime = "nodejs";
export const maxDuration = 120;

export async function POST(req: NextRequest) {
  let body: any = {};
  try {
    body = await req.json();
  } catch {}
  const scanId = String(body.scanId || "").trim();
  const sessionId = String(body.sessionId || "").trim();
  if (!scanId) return NextResponse.json({ error: "Missing scan id." }, { status: 400 });
  if (!dbConfigured()) {
    return NextResponse.json({ error: "Reports are not configured yet." }, { status: 503 });
  }

  const session = sessionId ? await readSession(sessionId) : null;
  const out = await fulfil(scanId, session);
  if (!out.ok) return NextResponse.json({ error: out.error }, { status: out.status });
  return NextResponse.json({ paid: true, report: out.report });
}
